SELECT 
FROM health_data
WHERE device_id = #{deviceId}
  AND timestamp BETWEEN #{start} AND #{end}
ORDER BY timestamp ASC

SELECT 
FROM health_data
WHERE device_id = #{deviceId}
  AND data_type = #{dataType}
ORDER BY timestamp DESC
LIMIT 1

SELECT 
FROM health_data
WHERE device_id = #{deviceId}
  AND data_type = #{dataType}
  AND timestamp = #{timestamp}
ORDER BY timestamp DESC
LIMIT 1
